import {bentRoute,routeLength,routeSlice,distanceAtX} from './routes.mjs';
/** Restore source cable terminals, routed segments and attached surface markings. */
export function addDetails({k,s,config,dial,wheel,wheelDisc,face,box,cyl,rod,put,fingerPorts,fingerGuide}){
 const detail=config.detail==='standard',connections=[],routes=[];
 const line=(o,a,b,normal=[0,0,1],width=.6,reason='engraved surface detail')=>k.mark(o,[a,b],{normal,width,reason});
 const ring=(o,x,y,z,r,width=.7)=>k.mark(o,k.ringPoints(r,z,32).map(([a,b,c])=>[a+x,b+y,c]),{closed:true,width});
 const sideRing=(o,r,z)=>{for(let i=0;i<48;i++){const a=i*Math.PI/24,b=(i+1)*Math.PI/24;line(o,[r*Math.cos(a),r*Math.sin(a),z],[r*Math.cos(b),r*Math.sin(b),z],[Math.cos((a+b)/2),Math.sin((a+b)/2),0],.4);}};
 const knurl=(o,r,z0,z1,count)=>{if(detail)for(let i=0;i<count;i++){const a=i*2*Math.PI/count;line(o,[r*Math.cos(a),r*Math.sin(a),z0],[r*Math.cos(a),r*Math.sin(a),z1],[Math.cos(a),Math.sin(a),0],.45,'rim groove');}};
 for(const [name,r,z0,z1,count] of [['dial.body',50,-1.3,1.5,150],['lock.pinion',8,-1.5,1.5,48],['lock.wheel',32,-1.5,1.5,192]]){const o=s.scene.getObjectByName(name);knurl(o,r,z0,z1,count);if(detail){sideRing(o,r,z0);sideRing(o,r,z1);}}
 if(detail){ring(face,0,0,1.63,33.5,.45);for(let i=0;i<10;i++){const a=i*Math.PI/5;k.label(wheelDisc,String(i),{at:[Math.sin(a)*22.6,-Math.cos(a)*22.6,2.02],u:[Math.cos(a),Math.sin(a),0],v:[Math.sin(a),-Math.cos(a),0],size:4.2});}for(const [name,r,z] of [['dial.hub',12,0],['piston.body',2.4,-2.9],['piston.body',2.4,2.9]])sideRing(s.scene.getObjectByName(name),r,z);}
 const topScrews=(name,points,z,r=.95)=>{const o=s.scene.getObjectByName(name);if(detail)for(const [x,y] of points){ring(o,x,y,z,r);ring(o,x,y,z,.45,.55);}};
 topScrews('stand.base',[[-75,-71],[75,-71],[-75,71],[75,71]],6.02,2.1);topScrews('hand.cover',[[-11.5,-11.4],[-11.5,11.4],[11.5,-11.4],[11.5,11.4]],.61,1.1);
 for(const [i,[x,y]] of [[-60,-56],[60,-56],[-60,56],[60,56]].entries()){const bolt=cyl('stand.plate.screw.'+i,x,y,2.4,10,.15);ring(bolt,0,0,.08,.55);}
 const palm=s.scene.getObjectByName('hand.palm');if(detail){for(const y of [-16.5,16.5])for(const x of [-7.5,6.5]){const pts=k.ringPoints(.95,0,24).map(([a,b])=>[x+a,y,1.2+b]);k.mark(palm,pts,{closed:true,normal:[0,Math.sign(y),0],width:.65});}for(const y of [-7,7])k.mark(palm,k.ringPoints(.95,0,24).map(([a,b])=>[-15,y+a,1.2+b]),{closed:true,normal:[-1,0,0],width:.65});}
 
 // Engraved circles on the split cap are clipped to each physical triangular host.
 if(detail){const cap=s.scene.getObjectByName('hand.f3.k0.1'),cross=(a,b,p)=>(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0]);for(const child of cap.children)for(const [r,width] of [[.85,.7],[.42,.55]]){const pts=k.ringPoints(r,.605,48),tri=child.userData.illustration.top;for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length];let lo=0,hi=1;for(let j=0;j<3;j++){const ca=cross(tri[j],tri[(j+1)%3],a),cb=cross(tri[j],tri[(j+1)%3],b),d=cb-ca;if(Math.abs(d)<1e-12){if(ca<0)hi=-1;}else{const t=-ca/d;if(d>0)lo=Math.max(lo,t);else hi=Math.min(hi,t);}}if(hi-lo>1e-8)k.mark(child,[a.map((v,j)=>v+(b[j]-v)*lo),a.map((v,j)=>v+(b[j]-v)*hi)],{width,normal:[0,0,1],reason:'engraved joint screw'});}}}
 s.scene.traverse(o=>{if(!o.userData.illustration||!/^hand\.f\d\.k[012]\./.test(o.name))return;if(detail){const z=o.userData.illustration.top[0][2];ring(o,0,0,z+.005,.85);ring(o,0,0,z+.006,.42);}});
 const portX=-10.7,clampX=-2.3,z=30.5,portY={red:-8.6,green:-5.4,blue:8.6};
 for(const [colour,y] of Object.entries(portY)){const port=rod('hand.port.'+colour,[portX,y,z],[portX+.7,y,z],1.15,dial,'brass');k.port(port,'out',{at:[0,0,.35],direction:[0,0,1],radius:.7});const clamp=rod('hand.clamp.'+colour,[clampX-.55,y,z],[clampX+.55,y,z],1.45,dial,'brass');sideRing(clamp,1.45,0);}
 box('hand.clamp.left',-3.6,-10.4,2.6,6.6,28.6,.45,.3,dial,'gunmetal');box('hand.clamp.right',-3.6,6.9,2.6,3.4,28.6,.45,.3,dial,'gunmetal');box('hand.terminal',7.3,-7,2.6,3.2,28.6,3.7,.5,dial,'gunmetal');
 for(const colour of ['red','green','blue']){const start=[portX,portY[colour],z];let points,trimEnd=0,finish;
  if(colour==='green'){finish=[7.3,portY[colour],z];points=[start,finish];}else{const port=fingerPorts.find(p=>p.id===(colour==='red'?1:3)),end=port.p;finish=end;const a=end.map((x,i)=>x-port.d1[i]*.6);const fitting=rod('hand.f'+port.id+'.port',end,a,.95,dial,'brass');k.port(fitting,'out',{at:[0,0,.3],direction:[0,0,1],radius:.7});points=[start,[-.4,portY[colour],z],end.map((x,i)=>x-port.d1[i]*7.6+(i===2?.3:0)),end];trimEnd=.6;}
  const route=bentRoute(points),total=routeLength(route),hit=distanceAtX(route,clampX),intervals=[[.7,hit-.55],[hit+.55,total-trimEnd]];
  intervals.forEach(([from,to],i)=>{const pts=routeSlice(route,from,to);if(i===0){pts[pts.length-1]=[clampX-.55,portY[colour],z];while(pts.length>2&&pts.at(-2)[0]>clampX-1.1)pts.splice(pts.length-2,1);pts.splice(pts.length-1,0,[clampX-1.1,portY[colour],z]);}else{pts[0]=[clampX+.55,portY[colour],z];while(pts.length>2&&pts[1][0]<clampX+1.1)pts.splice(1,1);pts.splice(1,0,[clampX+1.1,portY[colour],z]);if(colour!=='green'){const terminal=fingerPorts.find(p=>p.id===(colour==='red'?1:3)),end=terminal.p.map((x,j)=>x-terminal.d1[j]*.6);while(pts.length>2&&Math.hypot(...pts.at(-2).map((x,j)=>x-end[j]))<1.2)pts.splice(pts.length-2,1);pts[pts.length-1]=end;pts.splice(pts.length-1,0,end.map((x,j)=>x-terminal.d1[j]*1.2));}}const o=k.tube('cable.'+colour+'.'+i,{points:pts,radius:.7,segments:Math.max(4,Math.min(64,Math.ceil((to-from)*2))),radialSegments:24});put(o,[0,0,0],dial,'cable-'+colour);routes.push({name:o.name,object:o,points:pts,radius:.7});});connections.push({name:colour,start:routeSlice(route,.7,.71)[0],end:routeSlice(route,total-trimEnd-.01,total-trimEnd).at(-1),clampX,clampGap:1.1,upstreamEndpoint:finish});
 }
 const valve=box('hand.valve',3.4,2.8,3.4,3.6,28.6,5.2,.6,dial,'gunmetal');if(detail)for(const [x,y] of [[-.9,-1],[.9,1]])ring(valve,x,y,2.61,.4);
 rod('hand.hose.ferrule.0',[-10.7,4.6,31.9],[-9.4,4.6,31.9],1.25,dial,'brass');rod('hand.hose.ferrule.1',[3.4,4.6,31.9],[2.1,4.6,31.9],1.25,dial,'brass');
 const hose=k.tube('hand.hose',{points:[[-9.4,4.6,31.9],[-3.65,4.6,31.9],[2.1,4.6,31.9]],radius:.9,segments:24,radialSegments:24});put(hose,[0,0,0],dial,'steel');if(detail)k.routeRings(hose,{every:3,width:.5});routes.push({name:'hand.hose',object:hose,points:hose.userData.route.waypoints,radius:.9});
 if(fingerGuide){const {C2,d2,w,g2,origin}=fingerGuide,up=[-d2[2]*w[1],d2[2]*w[0],d2[0]*w[1]-d2[1]*w[0]],guide=k.prism('hand.f2.guide',{plan:[[-1.5,2.35],[1.5,2.35],[1.15,3.25],[-1.15,3.25]],height:3.6});const align=new k.Quaternion().setFromUnitVectors(new k.Vector3(0,0,1),new k.Vector3(...d2));guide.quaternion.copy(align);const currentU=new k.Vector3(1,0,0).applyQuaternion(align),axis=new k.Vector3(...d2),angle=Math.atan2(axis.dot(currentU.clone().cross(new k.Vector3(...w))),currentU.dot(new k.Vector3(...w)));guide.quaternion.premultiply(new k.Quaternion().setFromAxisAngle(axis,angle));put(guide,C2.map((x,i)=>x+d2[i]*2.9),g2,'gunmetal');void up;void origin;}
 return {routes,connections};
}
